// js
// DOLE Handbook on Workers' Statutory Monetary Benefits 2024 ch.1 §I, no work, no pay: the wage of a day taken off, over the working days of the period (proration_basis WORKING_DAYS).
// Fixed allowances fall with BASIC_AFTER_UNPAID_LEAVE, each in its own de minimis or wage checkpoint.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
if (unit === 'DAILY' || unit === 'HOURLY') return ctx.day_rate * ctx.entry.quantity;
const schedule = get(ctx.subject.employer, 'payment_schedule', {});
const halves = get(schedule, 'frequency', '') === 'SEMI_MONTHLY';
const coverage = ctx.run.salary_coverage;
const back = add_days(coverage.from, -1);
const from = ctx.entry.is_reversal !== true ? coverage.from : halves && Number(back.slice(8, 10)) > 15 ? add_days(month_start(back), 15) : month_start(back);
const to = ctx.entry.is_reversal !== true ? coverage.to : back;
const scheduled = get(schedule, 'non_working_weekdays', [0, 6]);
const week = Number(get(ctx.subject.employment.terms, 'normal_days_per_week', 7 - scheduled.length));
const off = week === 7 - scheduled.length ? scheduled : [0, 6, 5, 4, 3, 2, 1].slice(0, 7 - week);
const worksOn = (date) => {
	const day = ctx.work.days.find((row) => row.date === date);
	return day == null ? !off.includes(weekday(date)) : ['WORK', 'ABS'].includes(get(day, 'day_type', 'WORK'));
};
let working = 0;
for (let date = from; date <= to; date = add_days(date, 1)) if (worksOn(date)) working += 1;
const rate = Number(get(terms, 'rate.amount', 0));
const pay = unit === 'MONTHLY' && halves ? rate / 2 : rate;
return working > 0 ? (pay * ctx.entry.quantity) / working : 0;

